select orders.*,
       (first_week + floor(extract(epoch from o_orderdate::timestamp - first_week) / (14 * 86400)) * 14 * interval '1 day')::date as biweek
from (select orders.*,
             min(date_trunc('week', o_orderdate)) over () as first_week
      from orders
     ) orders;

SELECT li.l_orderkey, v.mindate AS minimum_date
FROM lineitem li
LEFT JOIN LATERAL (
  SELECT MIN(mindate) AS mindate
  FROM (VALUES (li.l_shipdate), (li.l_commitdate), (li.l_receiptdate)) AS x(mindate)
) v ON true;

SELECT to_timestamp(sub.avg_s)::date AS avg_date
FROM lineitem l
CROSS JOIN LATERAL (
  WITH secs AS (
    SELECT EXTRACT(EPOCH FROM l.l_shipdate) AS s
    UNION ALL
    SELECT EXTRACT(EPOCH FROM l.l_commitdate) AS s
  )
  SELECT AVG(s) AS avg_s FROM secs
) AS sub;

