select t.*, w.mode
from orders t
left join lateral (
  select shipmode as mode
  from (
    select l.l_shipmode as shipmode, count(*) over (partition by l.l_shipmode) as cnt
    from lineitem l
    where l.l_orderkey = t.o_orderkey
  ) s
  order by cnt desc, shipmode
  limit 1
) w on true;

